package kr.yunseok.touchmacro;
import org.junit.Test;
import static org.junit.Assert.*;
public class WatchConfigTest {
    @Test public void defaultIsEnterFifteenRoundsAndTenSecondRefresh(){WatchConfig p=new WatchConfig();p.validate();assertEquals(10,p.intervalSeconds);assertEquals(15,p.repetitions);assertEquals(30,p.swipeStartY(),0);assertEquals(75,p.swipeEndY(),0);assertTrue(p.tapFound);assertTrue(p.waitForRefresh);assertEquals(1,p.backCount);}
    @Test public void regionAndMacroSurviveSave(){WatchConfig p=new WatchConfig();p.rule.text="예약 가능";p.rule.left=15;p.rule.top=35;p.rule.right=65;p.rule.bottom=80;p.macroName="내 동작";p.intervalSeconds=90;p.direction="SCROLL_DOWN";p.backCount=2;p.tapFound=true;p.waitForRefresh=true;WatchConfig q=new WatchConfig(p.json());q.validate();assertEquals(p.rule.text,q.rule.text);assertEquals(15,q.rule.left,0);assertEquals(80,q.rule.bottom,0);assertEquals("내 동작",q.macroName);assertEquals(90,q.intervalSeconds);assertEquals(75,q.swipeStartY(),0);assertEquals(52.5,q.swipeEndY(),0);assertEquals(2,q.backCount);assertTrue(q.tapFound);assertTrue(q.waitForRefresh);}
    @Test(expected=IllegalArgumentException.class) public void rejectsEmptyText(){WatchConfig p=new WatchConfig();p.rule.text="";p.validate();}
    @Test(expected=IllegalArgumentException.class) public void rejectsBackwardsRegion(){WatchConfig p=new WatchConfig();p.rule.left=80;p.rule.right=20;p.validate();}
    @Test(expected=IllegalArgumentException.class) public void rejectsZeroInterval(){WatchConfig p=new WatchConfig();p.intervalSeconds=0;p.validate();}
    @Test public void ownCountOverridesMacroCountWithoutMultiplyingOrMutating(){Macro m=new Macro();m.steps.add(new Step("TAP"));m.steps.add(new Step("WAIT"));m.rounds=15;m.startAt=2;Macro prepared=new WatchConfig().prepareMacro(m);assertEquals(15,prepared.rounds);assertEquals(1,prepared.startAt);assertEquals(15,m.rounds);assertEquals(2,m.startAt);prepared.steps.get(0).x=12;assertEquals(50,m.steps.get(0).x,0);}
    @Test public void endlessSourceStillBecomesFinite(){Macro m=new Macro();m.steps.add(new Step("TAP"));m.rounds=0;assertEquals(15,new WatchConfig().prepareMacro(m).rounds);assertEquals(0,m.rounds);}
    @Test public void migratesFourthRoundButKeepsWordRegionAndMacro()throws Exception{org.json.JSONObject old=new WatchConfig().json();old.remove("repetitions");old.put("intervalSeconds",60).put("tapFound",false).put("waitForRefresh",false).put("macroName","선택한 매크로");old.getJSONObject("rule").put("text","예약 가능").put("top",20);WatchConfig p=new WatchConfig(old);assertEquals("예약 가능",p.rule.text);assertEquals(20,p.rule.top,0);assertEquals("선택한 매크로",p.macroName);assertEquals(10,p.intervalSeconds);assertEquals(15,p.repetitions);assertTrue(p.tapFound);assertTrue(p.waitForRefresh);}
    @Test public void fifthRoundCustomValuesAreNotReset(){WatchConfig p=new WatchConfig();p.repetitions=3;p.intervalSeconds=25;p.tapFound=false;p.waitForRefresh=false;p.entryMs=2500;WatchConfig q=new WatchConfig(p.json());assertEquals(3,q.repetitions);assertEquals(25,q.intervalSeconds);assertEquals(2500,q.entryMs);assertFalse(q.tapFound);assertFalse(q.waitForRefresh);}
    @Test(expected=IllegalArgumentException.class) public void rejectsZeroRepetitions(){WatchConfig p=new WatchConfig();p.repetitions=0;p.validate();}
    @Test(expected=IllegalArgumentException.class) public void rejectsAllDisabled(){Macro m=new Macro();Step s=new Step("TAP");s.enabled=false;m.steps.add(s);new WatchConfig().validateMacro(m);}
}
